// src/utils/array-utils.ts
var randomChoice = (array) => {
  const index = Math.floor(Math.random() * array.length);
  return array[index];
};

// src/utils/filters.ts
var byLength = (a, b) => b.length - a.length;

// src/utils/template-string-utils.ts
var replaceAllOfType = (template, toReplace, candidates) => {
  let updatedTemplate = template;
  while (updatedTemplate.includes(toReplace)) {
    const replacement = randomChoice(candidates);
    updatedTemplate = updatedTemplate.replace(toReplace, replacement);
  }
  return updatedTemplate;
};
var addFinalPunctuation = (template, candidates, weight) => {
  const toAppend = randomChoice(candidates);
  return Math.random() < weight ? `${template} ${toAppend}` : `${template}!`;
};
var filterTemplatesOnMaxLength = (templates, maxLength, inputs) => {
  const applicableTemplates = maxLength === void 0 ? templates : templates.filter((t) => templateMaxLength(t, inputs) <= maxLength);
  if (applicableTemplates.length === 0) throw new RangeError("No applicable templates found for given maxLength.");
  return applicableTemplates;
};
var updateIndefiniteArticles = (template) => {
  return template.replace(/ a ([aeiou])/g, " an $1").replace(/^a ([aeiou])/g, "an $1").replace(/ A ([aeiou])/g, " An $1").replace(/^A ([aeiou])/g, "An $1");
};
var templateMaxLength = (template, inputs) => {
  const longestNoun = inputs.nouns.sort(byLength)[0];
  const longestAdjective = inputs.adjectives.sort(byLength)[0];
  const longestQualifier = inputs.adverbs.sort(byLength)[0];
  const longestEmotion = inputs.emotions.sort(byLength)[0];
  const longestEmoji = inputs.emojiWeight <= 0 ? "!" : " \u{1F60E}";
  let longestVersionOfTemplate = replaceAllOfType(template, "{noun}", [longestNoun]);
  longestVersionOfTemplate = replaceAllOfType(longestVersionOfTemplate, "{adjective}", [longestAdjective]);
  longestVersionOfTemplate = replaceAllOfType(longestVersionOfTemplate, "{adverb}", [longestQualifier]);
  longestVersionOfTemplate = replaceAllOfType(longestVersionOfTemplate, "{emotion}", [longestEmotion]);
  longestVersionOfTemplate = `${longestVersionOfTemplate}${longestEmoji}`;
  return longestVersionOfTemplate.length;
};
var capitaliseFirstLetter = (template) => {
  return `${template[0].toUpperCase()}${template.slice(1)}`;
};
var fillTemplate = (template, inputs) => {
  const withNouns = replaceAllOfType(template, "{noun}", inputs.nouns);
  const withAdjectives = replaceAllOfType(withNouns, "{adjective}", inputs.adjectives);
  const withQualifiers = replaceAllOfType(withAdjectives, "{adverb}", inputs.adverbs);
  const withEmotions = replaceAllOfType(withQualifiers, "{emotion}", inputs.emotions);
  const withFinalPunctuation = addFinalPunctuation(withEmotions, inputs.emojis, inputs.emojiWeight ?? 0.5);
  const withCapitalisedFirstLetter = capitaliseFirstLetter(withFinalPunctuation);
  const withUpdatedArticles = updateIndefiniteArticles(withCapitalisedFirstLetter);
  return withUpdatedArticles;
};

// src/index.ts
var generateCompliment = (options = {}) => {
  const allTemplates = [...options.templates ?? sentenceTemplates, ...options.additionalTemplates ?? []];
  const inputs = {
    nouns: [...options.nouns ?? nouns, ...options.additionalNouns ?? []],
    adjectives: [...options.adjectives ?? adjectives, ...options.additionalAdjectives ?? []],
    adverbs: [...options.adverbs ?? adverbs, ...options.additionalQualifiers ?? []],
    emotions: [...options.emotions ?? emotions, ...options.additionalEmotions ?? []],
    emojis: [...options.emojis ?? emojis, ...options.additionalEmojis ?? []],
    emojiWeight: options.emojiWeight ?? 0.5
  };
  const applicableTemplates = filterTemplatesOnMaxLength(allTemplates, options.maxLength, inputs);
  const chosenTemplate = randomChoice(applicableTemplates);
  const filledTemplate = fillTemplate(chosenTemplate, inputs);
  return filledTemplate;
};
